<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, errorMessage } from '../api.js'
import { useAuth } from '../stores/auth.js'
const auth = useAuth(), form = reactive({ displayName: '', timeZone: '' }), busy = ref(false), error = ref(''), success = ref('')
onMounted(async () => { try { const { data } = await api.get('/profile'); auth.setUser(data); Object.assign(form, data) } catch (e) { error.value = errorMessage(e) } })
async function submit() { busy.value = true; error.value = ''; success.value = ''; try { const { data } = await api.put('/profile', { displayName: form.displayName, timeZone: form.timeZone }); auth.setUser(data); success.value = 'Profile saved.' } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE, YOUR WAY</span><h1>Profile & settings</h1><p>The little details that make this space yours.</p></div></div><div class="editor-layout"><form class="panel editor-form" @submit.prevent="submit"><h2>Personal details</h2><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><label>Email address<input :value="auth.user?.email" type="email" disabled><small class="field-help">Your account’s login address.</small></label><label>Display name<input v-model.trim="form.displayName" required maxlength="100" autocomplete="name"></label><label>Preferred time zone<input v-model.trim="form.timeZone" required maxlength="64" placeholder="Asia/Kolkata"><small class="field-help">Used for history and new reminder defaults. Existing reminders keep their own selected zone.</small></label><div class="form-actions"><button class="button primary" :disabled="busy">{{ busy ? 'Saving…' : 'Save changes' }}</button></div></form><aside class="tip-card"><span class="tip-symbol">◈</span><h3>A private workspace.</h3><p>Your reminders and history are scoped to your account.</p><hr><strong>Session management</strong><p>Access tokens expire automatically. Signing out revokes all current tokens for your account. If offline, local sign-out clears this browser; server revocation requires a connection.</p></aside></div></template>
